mapper.select:
SELECT FROM brand WHERE deleted_at IS NULL
AND id IN #{id}
AND 1 = 0

SELECT  FROM brand
WHERE deleted_at IS NULL
AND name = #{query.name}
AND letter = #{query.letter}
ORDER BY id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT  FROM brand
WHERE deleted_at IS NULL
AND name LIKE #{name} ESCAPE '\'

    AND EXISTS (
        SELECT 1
        FROM category c
        JOIN category_brand cb ON cb.category_id = c.id AND cb.tenant_id = c.tenant_id
        WHERE c.name = #{categoryName}
            AND cb.brand_id = brand.id
            AND c.tenant_id = brand.tenant_id
            AND c.deleted_at IS NULL
            AND cb.deleted_at IS NULL
    )

AND letter = #{letter}
AND seq >= #{seqMin}
AND seq <= #{seqMax}
ORDER BY seq DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM brand
WHERE deleted_at IS NULL
AND name LIKE #{name} ESCAPE '\'

    AND EXISTS (
        SELECT 1
        FROM category c
        JOIN category_brand cb ON cb.category_id = c.id AND cb.tenant_id = c.tenant_id
        WHERE c.name = #{categoryName}
            AND cb.brand_id = brand.id
            AND c.tenant_id = brand.tenant_id
            AND c.deleted_at IS NULL
            AND cb.deleted_at IS NULL
    )

AND letter = #{letter}
AND seq >= #{seqMin}
AND seq <= #{seqMax}

SELECT COUNT(*) FROM brand
WHERE deleted_at IS NULL AND name = #{name}
AND id != #{excludeId}
